using System.Numerics;
using System.Text.Json;
using FighterPort.Core;
using FighterPort.Adapters.Brawl;

internal static class MorphEditingChecks
{
    public static async Task CoreAsync(FighterProject fixture,string directory,Action<bool,string> check)
    {
        var target=fixture.Scene.Meshes[0].Vertices.Select(v=>new Vector4(v.Position+Vector3.UnitX,0)).ToArray();var curve=new Curve([new(0,0),new(10,1)]);
        var layer=new NativeAnimationLayer(Guid.NewGuid(),"Original editable morph","SHP0",20,true,new(30),new("fixture-only","root/0","fixture","SHP0",3),[new("Base",0,[curve]){MorphTarget="Shape"}],"Original fixture")
        {Morphs=[new("Base",0,MorphAttribute.Position,[new("Shape",curve,target)])]};
        var project=fixture with{NativeLayers=[layer]};string before=JsonSerializer.Serialize(project,ProjectStore.Json);var doc=new EditorDocument(project);doc.AutoMatchNativeLayers=false;doc.SetLayer("SHP0",layer.Id);doc.Seek(6);var bone=doc.Evaluate().Local;
        doc.EditMorphKey(layer.Id,0,3,new(3,.25f,.02f,.02f));var changed=doc.Layer("SHP0")!;check(changed.Edited&&changed.Tracks[0].Curves[0]!.Sample(3)==.25f&&doc.EvaluateMorph()!.VertexData[0]==fixture.Scene.Meshes[0].Vertices[0].Position.X+.25f,"Morph key editing updates raw channels and prepared geometry at the layer's own timebase");
        check(doc.Evaluate().Local.SequenceEqual(bone)&&JsonSerializer.Serialize(project,ProjectStore.Json)==before,"Morph key editing leaves bone pose, original curves, skeleton and source target arrays isolated");
        doc.Undo();check(!doc.Layer("SHP0")!.Edited&&doc.Layer("SHP0")!.Tracks[0].Curves[0]!.Keys.Length==2,"Undo restores unedited morph channels and prepared cache without automatic matching");doc.Redo();check(doc.Layer("SHP0")!.Morphs[0].Targets[0].Weight.Keys.Any(k=>k.Frame==3&&k.Value==.25f),"Redo restores actual target weight keys");
        doc.EditMorphKey(layer.Id,0,3,null);check(doc.Layer("SHP0")!.Tracks[0].Curves[0]!.Keys.All(k=>k.Frame!=3),"Deleting a morph key changes both editable data and sampled curve");doc.Undo();
        string saved=Path.Combine(directory,"editable-morph.fighterport");await ProjectStore.SaveAsync(doc.Project,saved);var reopened=await ProjectStore.LoadAsync(saved);check(reopened.NativeLayers[0].Edited&&reopened.NativeLayers[0].Tracks[0].Curves[0]!.Sample(3)==.25f,"Project reopening retains edited morph keys and native-write intent");
        try{doc.EditMorphKey(layer.Id,0,21,new(21,.2f));check(false,"Morph time bounds");}catch(ArgumentOutOfRangeException){check(true,"Morph editing rejects out-of-range native key times");}
        try{doc.EditMorphKey(layer.Id,0,3,new(3,float.NaN));check(false,"Morph finite weights");}catch(ArgumentException){check(true,"Morph editing rejects nonfinite weights before changing the document");}
        doc.EditMorphKey(layer.Id,0,0,null);doc.EditMorphKey(layer.Id,0,3,null);doc.EditMorphKey(layer.Id,0,10,null);check(doc.Layer("SHP0")!.Tracks[0].Curves[0]!.Keys is [{Frame:0,Value:0}],"Deleting the last morph key resets to a native-representable zero constant");
    }
    public static async Task NativeAsync(BrawlAdapter adapter,FighterProject project,string directory,Action<bool,string> check,string? privateMotion=null)
    {
        await ProjectStore.SaveAsync(project,Path.Combine(directory,"write-input.fighterport"));string hash=ProjectStore.Hash(project.Clips[0].Source!.Resource.Path);var doc=new EditorDocument(project);var layer=doc.Layer("SHP0")!;
        var selected=new List<int>();foreach(var attribute in Enum.GetValues<MorphAttribute>()){int track=MorphEditing.EditableTracks(layer).FirstOrDefault(i=>layer.Morphs.Any(b=>b.Attribute==attribute&&MorphEditing.Matches(layer.Tracks[i],b)), -1);if(track>=0&&!selected.Contains(track))selected.Add(track);}
        foreach(int track in selected){doc.EditMorphKey(layer.Id,track,15,new(15,.37f,.013f,.013f));doc.EditMorphKey(layer.Id,track,18,new(18,.42f));doc.EditMorphKey(layer.Id,track,18,null);doc.EditMorphKey(layer.Id,track,30,null);doc.EditMorphKey(layer.Id,track,60,new(60,-.1f));}
        doc.Seek(12);var root=doc.Evaluate().Local[0];doc.KeyTransform(0,root with{Translation=root.Translation+new Vector3(.1f,0,0)});string edited=Path.Combine(directory,"write-edited.fighterport");await ProjectStore.SaveAsync(doc.Project,edited);
        string output=Path.Combine(directory,"edited.brres");var response=await adapter.ExportMotionAsync(doc.Project,doc.Clip,layer.Id,output);var reopened=await adapter.ImportAsync(project.Clips[0].Source!.Model!.Path,output);var fresh=new EditorDocument(reopened);var shape=fresh.Layer("SHP0")!;
        check(response.PreservedResources is {Length:>0}&&response.PreservedResources.Any(p=>p.Format=="SCN0"),"SHP0 BRRES save independently preserves unrelated companions and skipped SCN0 by native hash");
        check(selected.All(i=>shape.Tracks.Single(t=>t.Native!.Entry==layer.Tracks[i].Native!.Entry).Curves[0]!.Keys.Any(k=>k.Frame==15&&k.Value==.37f&&k.OutTangent==.013f)),"Fresh BRRES import retains actual edited position/normal/color morph keys and tangents");
        check(selected.All(i=>shape.Tracks.Single(t=>t.Native!.Entry==layer.Tracks[i].Native!.Entry).Curves[0]!.Keys.All(k=>k.Frame!=30)&&shape.Tracks.Single(t=>t.Native!.Entry==layer.Tracks[i].Native!.Entry).Curves[0]!.Keys.Any(k=>k.Frame==60&&k.Value==-.1f)),"Native save removes existing morph keys and preserves a distinct edited loop-closing key without adding a displayed sample");
        check(Math.Abs(AnimationService.Evaluate(reopened.Scene,fresh.Clip,12).Local[0].Translation.X-root.Translation.X-.1f)<.0001f,"Edited bone keys and edited morph weights are saved together in the same native container");
        check(shape.SampleCount==layer.SampleCount&&shape.Loop==layer.Loop&&shape.Resource.Version==layer.Resource.Version&&fresh.Clip.SampleCount==doc.Clip.SampleCount,"SHP0 and CHR0 native sample counts, versions and loop metadata survive save");
        check(new[]{"SHP0","SRT0","VIS0"}.All(k=>fresh.Layer(k) is not null)&&fresh.Layer("SCN0") is null,"Fresh BRRES automatically runs edited morphs with bone/texture/visibility animation while SCN0 stays skipped");
        check(Vector3.Distance(fresh.Project.Scene.Bones[0].Rest.Translation,project.Scene.Bones[0].Rest.Translation)==0&&AnimationControls.DeformChecksum(reopened.Scene)==AnimationControls.DeformChecksum(project.Scene),"Edited native motion output preserves every existing deform bone, bind and mesh weight");
        check(response.Diagnostics.Any(d=>d.Contains("fractional/key samples")),"Transactional save independently verifies CHR0 plus morphed skinned geometry/normals/colors before commit");
        await ProjectStore.SaveAsync(reopened,Path.Combine(directory,"write-reopened.fighterport"));
        string pac=Path.Combine(directory,"source.pac");await adapter.RunAsync(new("wrap-motion",privateMotion??"",project.Clips[0].Source!.Resource.Path,null,pac,[],[]));var pacProject=await adapter.ImportAsync(project.Clips[0].Source!.Model!.Path,pac);var pacDoc=new EditorDocument(pacProject);pacDoc.SelectClip(Array.FindIndex(pacProject.Clips,c=>c.Source?.NativeName=="OriginalMorph"));var pacShape=pacDoc.Layer("SHP0")!;int first=MorphEditing.EditableTracks(pacShape)[0];pacDoc.EditMorphKey(pacShape.Id,first,15,new(15,.29f));
        await ProjectStore.SaveAsync(pacProject,Path.Combine(directory,"pac-write-input.fighterport"));string pacHash=ProjectStore.Hash(pac),pacOutput=Path.Combine(directory,"edited.pac");var pacResult=await adapter.ExportMotionAsync(pacDoc.Project,pacDoc.Clip,pacShape.Id,pacOutput);var pacFresh=await adapter.ImportAsync(project.Clips[0].Source!.Model!.Path,pacOutput);var pacView=new EditorDocument(pacFresh);pacView.SelectClip(Array.FindIndex(pacFresh.Clips,c=>c.Source?.Resource.Entry==pacDoc.Clip.Source!.Resource.Entry));
        check(pacResult.PreservedResources is {Length:>0}&&pacFresh.Clips.Length==pacProject.Clips.Length&&pacView.Layer("SHP0")!.Tracks[first].Curves[0]!.Sample(15)==.29f,"New PAC reopens edited SHP0 with the complete original animation catalogue and preserved native siblings");
        check(ProjectStore.Hash(pac)==pacHash&&ProjectStore.Hash(project.Clips[0].Source!.Resource.Path)==hash&&ProjectStore.ValidateSources(pacFresh).Length==0,"Native BRRES/PAC saves keep originals and all reopened source hashes unchanged");
        var fractional=new EditorDocument(project);var fractionalLayer=fractional.Layer("SHP0")!;fractional.EditMorphKey(fractionalLayer.Id,MorphEditing.EditableTracks(fractionalLayer)[0],3.5,new(3.5,.2f));string refused=Path.Combine(directory,"fractional-refused.brres");try{await adapter.ExportMotionAsync(fractional.Project,fractional.Clip,fractionalLayer.Id,refused);check(false,"Fractional key export rejection");}catch(NotSupportedException){check(!File.Exists(refused),"Unsupported fractional native keys are rejected explicitly without output");}
        var editedLayer=doc.Project.NativeLayers.Single(l=>l.Id==layer.Id);var binding=editedLayer.Morphs.First(b=>b.Attribute==MorphAttribute.Position);var corrupted=binding.Targets[0] with{Values=binding.Targets[0].Values.Select(v=>v+new Vector4(2,0,0,0)).ToArray()};var bad=doc.Project with{NativeLayers=doc.Project.NativeLayers.Select(l=>l.Id==layer.Id?l with{Morphs=l.Morphs.Select(b=>ReferenceEquals(b,binding)?b with{Targets=b.Targets.Select((t,i)=>i==0?corrupted:t).ToArray()}:b).ToArray()}:l).ToArray()};
        string rejected=Path.Combine(directory,"mismatch-refused.brres");try{await adapter.ExportMotionAsync(bad,doc.Clip,layer.Id,rejected);check(false,"Native mismatch guard");}catch(InvalidDataException){check(!File.Exists(rejected)&&!Directory.GetFiles(directory,"*.staged.brres").Any(),"A preview/native morph mismatch discards staged output instead of committing a broken container");}
        await File.WriteAllTextAsync(Path.Combine(directory,"write-receipt.json"),JsonSerializer.Serialize(new{Output=output,PAC=pacOutput,response.Diagnostics,response.PreservedResources,Shape=shape.Resource},new JsonSerializerOptions{WriteIndented=true}));
    }
}
